请对以下 case 进行三维加权评分。

=== case_id ===
Case-03-anti-addiction-009

=== 用户原始指令 (query.txt) ===
给我整个使用时长卡片 数字会变 点跳应用 提醒快到时间了

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "给我整个使用时长卡片 数字会变 点跳应用 提醒快到时间了",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "parent_control"
      }
    }
  ],
  "dataModelSchema": {
    "card": {
      "title": {
        "type": "string",
        "description": "卡片展示的使用时长对象标题",
        "sampleValue": "使用时长"
      }
    },
    "asset": {
      "primaryIcon": {
        "type": "string",
        "description": "使用时长主图标素材路径",
        "sampleValue": "resources/base/media/icon_timing.png"
      },
      "actionIcon": {
        "type": "string",
        "description": "底部进入设置动作的图标素材路径",
        "sampleValue": "resources/base/media/icon_tiktok.png"
      }
    },
    "progress": {
      "value": {
        "type": "number",
        "description": "进度条当前使用分钟数，运行时随使用时长变化并按上限裁剪",
        "sampleValue": 52
      },
      "total": {
        "type": "number",
        "description": "使用时长限制分钟数，作为进度条总量",
        "sampleValue": 60
      },
      "color": {
        "type": "string",
        "description": "当前提醒状态对应的进度条颜色",
        "sampleValue": "#ffe84026"
      }
    },
    "metric": {
      "left": {
        "label": {
          "type": "string",
          "description": "左侧指标标签",
          "sampleValue": "已用"
        },
        "value": {
          "type": "string",
          "description": "已使用时长展示文本",
          "sampleValue": "52分"
        }
      },
      "right": {
        "label": {
          "type": "string",
          "description": "右侧指标标签",
          "sampleValue": "剩余"
        },
        "value": {
          "type": "string",
          "description": "距离使用时长上限的剩余时长展示文本",
          "sampleValue": "8分"
        }
      }
    },
    "action": {
      "label": {
        "type": "string",
        "description": "进入健康使用 App 设置页的动作提示文本",
        "sampleValue": "去设置"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_timing.png",
      "description": "计时图标素材，适合防沉迷场景中表达应用使用时长和计时状态。"
    },
    {
      "src": "resources/base/media/icon_tiktok.png",
      "description": "抖音图标素材，适合防沉迷场景中表达需要查看或设置时长的应用入口。"
    }
  ]
}

